package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Set;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.escalation.DisposableEmailException;

/**
 * Rejects a new owner whose email domain is on the disposable-domain blocklist. Runs after Build so the
 * email is already normalized to lower case by {@link Owner#setEmail}, and before Save so the reject is a
 * 400 rather than a persisted owner.
 */
public class RejectDisposableEmail {

    private static final Set<String> BLOCKED = Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");

    public void service(@Val Owner owner) throws DisposableEmailException {
        String email = owner.getEmail();
        if (email == null) {
            return;
        }
        int at = email.lastIndexOf('@');
        if (at >= 0 && BLOCKED.contains(email.substring(at + 1))) {
            throw new DisposableEmailException(email);
        }
    }
}

==== ValidatePostcode.java ====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;

/**
 * When an owner supplies a postcode, rejects it when it falls outside the inclusive range for the
 * city's region (Sydney/NSW 2000-2099, Melbourne/VIC 3000-3099, Brisbane/QLD 4000-4099). A city
 * with no known region accepts any 4-digit postcode, and an absent postcode is always accepted.
 * The 4-digit shape is already enforced by the request DTO, so a present postcode parses cleanly.
 */
public class ValidatePostcode {

    private static final Map<String, int[]> REGION_RANGES = Map.of(
            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});

    private static final Map<String, String> CITY_REGION = Map.of(
            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    public void service(@Val Owner owner) throws InvalidPostcodeException {
        String postcode = owner.getPostcode();
        if (postcode == null) {
            return;
        }
        String region = CITY_REGION.get(owner.getCity());
        if (region == null) {
            return;
        }
        int[] range = REGION_RANGES.get(region);
        int value = Integer.parseInt(postcode);
        if (value < range[0] || value > range[1]) {
            throw new InvalidPostcodeException(owner.getCity(), postcode);
        }
    }
}

==== AssignHousehold.java ====
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns every owner a deterministic {@code householdId}: the first 12 hex characters of SHA-256
 * over {@code normalizedLastName + '|' + postcode}. Owners with the same last name and postcode are
 * therefore the same household and share this id automatically, with no opt-in or back-fill. Runs
 * before the household duplicate block so that block can compare on the computed id.
 */
public class AssignHousehold {

    public void service(@Val Owner owner) {
        String key = normalize(owner.getLastName()) + "|" + orEmpty(owner.getPostcode()) + "|V2";
        owner.setHouseholdId(hash12(key));
    }

    /** First 12 lower-case hex characters of SHA-256 over the UTF-8 bytes of {@code key}. */
    private static String hash12(String key) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(12);
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02x", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException(ex);
        }
    }

    private static String normalize(String value) {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
    }

    private static String orEmpty(String value) {
        return value == null ? "" : value;
    }
}

==== EnsureUniqueIdentity.java ====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;

/**
 * Rejects a new owner whose whole {@link OwnerIdentity#key(Owner) identityKey} equals an existing
 * owner's. This consolidates the former separate telephone, email and household checks into one key,
 * so an exact full-key match is the only conflict. Runs after {@link AssignHousehold} (which fixes the
 * householdId part) and before Save, so the collision is a 409, not a persisted duplicate.
 */
public class EnsureUniqueIdentity {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) throws DuplicateTelephoneException {
        String identityKey = OwnerIdentity.key(owner);
        for (Owner existing : ownerRepository.findAll()) {
            if (Boolean.TRUE.equals(existing.getDeleted())) {
                continue;
            }
            if (identityKey.equals(OwnerIdentity.key(existing))) {
                throw new DuplicateTelephoneException(owner.getTelephone());
            }
        }
    }
}

==== AssignCustomerCode.java ====
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the owner's {@code memberId} as {@code <REGION><FY><HASH8><CHK>}: the region code derived
 * from the postcode (see {@link OwnerLocality#forPostcode}), the two-digit fiscal year of the
 * registration date (see {@link FiscalYear#twoDigit}), the first eight upper-case hex characters of
 * SHA-256 over the normalized telephone (set by {@link BuildOwner}) concatenated with the last name,
 * and a single Luhn check digit over the digits of {@code <REGION><FY><HASH8>} (see
 * {@link CustomerCodeCheckDigit}). The id is a pure function of the owner's identity, so it carries no
 * sequence number.
 */
public class AssignCustomerCode {

    public void service(@Val Owner owner) {
        String region = OwnerLocality.regionV2(owner.getPostcode(), owner.getCity());
        String fy = FiscalYear.twoDigit(owner.getRegistrationDate());
        String hash8 = hash8(owner.getTelephone() + owner.getLastName());
        String base = region + fy + hash8;
        owner.setCustomerCode(base + CustomerCodeCheckDigit.of(base));
    }

    /** First eight upper-case hex characters of SHA-256 over the UTF-8 bytes of {@code value}. */
    private static String hash8(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(8);
            for (int i = 0; i < 4; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException(ex);
        }
    }
}

==== DeduplicateCustomerCode.java ====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.HashSet;
import java.util.Set;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * De-duplicates the {@code customerCode} assigned by {@link AssignCustomerCode}. When the computed
 * code already belongs to an existing owner, appends {@code -<n>} with the smallest {@code n} of 2 or
 * more that makes it unique. Runs after Assign and before Save, so distinct owners always persist
 * distinct customerCodes.
 */
public class DeduplicateCustomerCode {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String base = owner.getCustomerCode();
        Set<String> taken = new HashSet<>();
        for (Owner existing : ownerRepository.findAll()) {
            taken.add(existing.getCustomerCode());
        }
        String code = base;
        for (int n = 2; taken.contains(code); n++) {
            code = base + "-" + n;
        }
        owner.setCustomerCode(code);
    }
}

