package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Records the owner's {@code namesakeCount}: the number of existing owners sharing its first and last
 * name, compared case-insensitively. Runs before the owner is saved, so it counts only the owners that
 * existed before this create.
 */
public class CountNamesakes {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String firstName = owner.getFirstName();
        String lastName = owner.getLastName();
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (firstName.equalsIgnoreCase(existing.getFirstName())
                    && lastName.equalsIgnoreCase(existing.getLastName())) {
                count++;
            }
        }
        owner.setNamesakeCount(count);
    }
}

==== CapMembershipLevel.java ====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Caps a new owner's membership level at one above the highest level among their existing household
 * members (same householdId, not deleted). With no such member the computed level stands, so no cap is
 * stored. Runs after {@link CountNamesakes} so the computed level is final, and before Save so the cap
 * persists and later reads see it.
 */
public class CapMembershipLevel {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String householdId = owner.getHouseholdId();
        Integer highest = null;
        for (Owner existing : ownerRepository.findAll()) {
            if (Boolean.TRUE.equals(existing.getDeleted())) {
                continue;
            }
            if (householdId != null && householdId.equals(existing.getHouseholdId())) {
                int level = effectiveLevel(existing);
                if (highest == null || level > highest) {
                    highest = level;
                }
            }
        }
        if (highest != null) {
            owner.setMembershipLevel(Math.min(OwnerMembershipLevel.of(owner), highest + 1));
        }
    }

    /** An existing member's effective level: its stored cap when present, otherwise its computed level. */
    private static int effectiveLevel(Owner owner) {
        return owner.getMembershipLevel() != null ? owner.getMembershipLevel() : OwnerMembershipLevel.of(owner);
    }
}

==== EnsureCityCapacity.java ====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;

/**
 * Rejects a new owner whose city already contains {@value #CAPACITY} or more owners, comparing city
 * names case-insensitively. Runs before Save so a full city is a 409, not a persisted overflow. Also
 * flags {@code capacityWarning} when the city is within {@value #WARN_THRESHOLD}..{@value #CAPACITY}-1
 * owners, so an accepted owner still signals that its city is approaching the hard limit.
 */
public class EnsureCityCapacity {

    private static final int CAPACITY = 50;

    private static final int WARN_THRESHOLD = 40;

    public void service(@Val Owner owner, OwnerRepository ownerRepository) throws CityAtCapacityException {
        String city = owner.getCity();
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (city != null && city.equalsIgnoreCase(existing.getCity())) {
                count++;
            }
        }
        if (count >= CAPACITY) {
            throw new CityAtCapacityException(city, count);
        }
        owner.setCapacityWarning(count >= WARN_THRESHOLD);
    }
}

==== EnsureDailyLimit.java ====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.DailyLimitExceededException;

/**
 * Rejects a new owner once {@value #DAILY_LIMIT} or more owners have already been created today
 * (by registrationDate). Runs before Save so an over-limit create is a 429, not a persisted overflow.
 */
public class EnsureDailyLimit {

    private static final int DAILY_LIMIT = 100;

    public void service(@Val Owner owner, OwnerRepository ownerRepository) throws DailyLimitExceededException {
        LocalDate today = owner.getRegistrationDate();
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (today.equals(existing.getRegistrationDate())) {
                count++;
            }
        }
        if (count >= DAILY_LIMIT) {
            throw new DailyLimitExceededException(count);
        }
    }
}

