        AUDIT.info(
                "{\"schemaVersion\":2,\"seq\":{},\"ownerId\":{},\"memberId\":\"{}\",\"membershipLevel\":{},\"ownerSegment\":\"{}\",\"event\":\"OWNER_CREATED\"}",
                SEQ.incrementAndGet(), owner.getId(), primaryIdentifier(owner), OwnerMembershipLevel.of(owner),
                OwnerSegment.of(owner));
